sys_variable_value.value:
// ATF-CP-UI-06: Customer Order Detail UI
await sn_atf.navigate('/x_2056099_indust_0_customer_portal.do#orders');
await sn_atf.delay(3000);
var notLinked = await screen.queryByText('Customer Account Not Linked');
if (notLinked) {
    expect(notLinked).toBeVisible();
} else {
    await screen.findByText('My Orders', { exact: false }, { timeout: 15000 });
    var rows = await screen.queryAllBySelector('tbody tr');
    if (rows && rows.length > 0) {
        await user.click(rows[0]);
        await sn_atf.delay(2000);
        var backBtn = await screen.findByText(/Back to Orders/i, {}, { timeout: 10000 });
        expect(backBtn).toBeVisible();
        var orderInfo = await screen.queryByText('Order Information');
        if (orderInfo) expect(orderInfo).toBeVisible();
        var numberField = await screen.queryByText('Number');
        if (numberField) expect(numberField).toBeVisible();
        var statusField = await screen.queryByText('Status');
        if (statusField) expect(statusField).toBeVisible();
        var orderDateField = await screen.queryByText('Order Date');
        if (orderDateField) expect(orderDateField).toBeVisible();
        var deliveryField = await screen.queryByText('Requested Delivery');
        if (deliveryField) expect(deliveryField).toBeVisible();
        var totalQtyField = await screen.queryByText('Total Quantity');
        if (totalQtyField) expect(totalQtyField).toBeVisible();
        var itemsSection = await screen.queryByText(/Order Items/i);
        if (itemsSection) expect(itemsSection).toBeVisible();
        var deliveryLocField = await screen.queryByText('Delivery Location');
        if (deliveryLocField) expect(deliveryLocField).toBeVisible();
    }
}
